## ----rates-ferrn, echo=FALSE, eval=TRUE, out.width="80%", fig.align='center', fig.width=8, fig.height=7, layout= "l-body", fig.cap="Splines index value along the interpolated optimization path in the guided tour using geodesic optimization (GEOO) (top), simulated annealing with geodesic interpolation  (SAGEO) (middle) and with Givens interpolation (SAGIV) (bottom). Points indicate index values at target planes selected during the optimization, and the horizontal line shows the maximum across the three searches. With GEOO no within-plane rotation is possible and although the optimization always heads towards higher index values it finishes at a different frame in the same plane, with a lower than possible index value. With SAGEO, a different frame in the same plane interferes with the optimization. This does not happen with SAGIV, allowing the search to find the optimal view.", fig.alt="Three trace plots with points and connecting lines. The top plot is very smoothly increasing to a maximum value, whereas the bottom two plots show up and down patterns."----
load("data/rates_tour_records.RData")
library(ferrn)

max_idx <- max(get_interp_last(record_search_givens)$index_val)

p1 <- get_interp(record_search_geodesic) %>%
  ggplot(aes(id, index_val)) +
  geom_line() +
  geom_point(data = dplyr::bind_rows(get_start(record_search_geodesic),
                                     get_interp_last(record_search_geodesic))) +
  ylim(0,1) +
  geom_hline(yintercept = max_idx, color = "sienna3") +
  xlab(NULL) +
  ylab(NULL) +
  theme_bw()

             
p2 <- get_interp(record_search_better) %>%
  ggplot(aes(id, index_val)) +
  geom_line() +
  geom_point(data = dplyr::bind_rows(get_start(record_search_better),
                                     get_interp_last(record_search_better))) +
  ylim(0,1)+
  geom_hline(yintercept = max_idx, color = "sienna3") +
  xlab(NULL) +
  ylab("Index value") +
  theme_bw() 
          

p3 <- get_interp(record_search_givens) %>%
  ggplot(aes(id, index_val)) +
  geom_line() +
  geom_point(data = dplyr::bind_rows(get_start(record_search_givens),
                                     get_interp_last(record_search_givens))) +
  ylim(0,1)+
  geom_hline(yintercept = max_idx, color = "sienna3") +
  xlab("Interpolation step") +
  ylab(NULL) +
  theme_bw() 

cowplot::plot_grid(p1, p2, p3, ncol = 1, align = "hv" )


